    l_x20 : getr R 20%bv = Z_to_bv 64 SHBASE; l_x21 : getr R 21%bv = Z_to_bv 64 (obj / 8 + SHBASE);
    l_x22 : getr R 22%bv = s6; l_x23 : getr R 23%bv = s7; l_x24 : getr R 24%bv = s8; l_x25 : getr R 25%bv = s9;
    l_x26 : getr R 26%bv = s10; l_x27 : getr R 27%bv = s11;
